def cid(i): return ('AH' if i[0] in 'AB' else 'AS')+i
cards=[];quiz=[]
# حُذفت لأنها تكرّر بطاقات أخرى (المراجعة الشاملة 2026-11-26): رقية KN17، أمامة P04، طلحة KB09؛ تبقى أسطرها في lines.json
SKIP={'B04','B10','S16'}
for i,x in L.items():
    if i in SKIP: continue
    fam=i[0] in 'AB'
    cards.append({'id':cid(i),'chapter':CH,'title':TITLE[i],'text':x['text'],'source':x['source'],
      'grade':x['grade'],'theme':'plum' if fam else 'navy','long':False,'hadith':None,'kick':'من أهل بيته ﷺ' if fam else 'من أصحابه ﷺ','line':i})
    q,a,w=Q[i]; assert len(set(w+[a]))==4,i
    quiz.append({'card':cid(i),'q':q,'a':a,'w':w})
assert set(Q)==set(L)
print(len(cards),'cards',len(quiz),'questions')
if '--write' in sys.argv:
    for f in ['public/cards.json','data/cards.json']:
        d=json.load(open(f)); ids={c['id'] for c in d['cards']}
        assert not ids & {c['id'] for c in cards}
        d['cards']+=cards; d['version']+=1
        json.dump(d,open(f,'w'),ensure_ascii=False,indent=1); print(f,d['version'],len(d['cards']))
    json.dump(quiz,open('data/quiz/batch12.json','w'),ensure_ascii=False,indent=1)
